import{_ as r,C as o,o as d,c as n,aj as e,E as i}from"./framework.js";const f=JSON.parse('{"title":"Product Management (List) | Commerce | Admin CMS","description":"Maintain site sellable products list, filters, and entry points; per-product form and variants in Product detail (create and edit).","frontmatter":{"title":"Product Management (List) | Commerce | Admin CMS","description":"Maintain site sellable products list, filters, and entry points; per-product form and variants in Product detail (create and edit).","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/commerce/product-management.html"}]]},"headers":[],"relativePath":"cms/commerce/product-management.md","filePath":"en/cms/commerce/product-management.md","lastUpdated":1781010536000}'),s={name:"cms/commerce/product-management.md"};function c(l,t,p,m,u,g){const a=o("DocImage");return d(),n("div",null,[t[0]||(t[0]=e('<h1 id="product-management-list" tabindex="-1">Product Management (List) <a class="header-anchor" href="#product-management-list" aria-label="Permalink to &quot;Product Management (List)&quot;">​</a></h1><blockquote><p>Menu: <strong>Commerce -&gt; Product Management</strong><br> Deep link: <code>/_Admin/commerce/product-management?SiteId={siteGuid}</code></p></blockquote><p>Maintain site sellable products <strong>list, filters, and entry points</strong>; per-product form and variants in <a href="./product-management-detail.html">Product detail (create and edit)</a>.</p><div class="tip custom-block"><p class="custom-block-title">Prerequisite</p><p>Requires <a href="./product-types.html">product types</a>; categories optional, see <a href="./product-categories.html">product categories</a>. Global toggles and custom fields in <a href="./settings.html">settings</a>.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In the <a href="./../navigation.html#edit-menu">Edit menu</a>, enable <strong>Commerce -&gt; Product Management</strong> (and the parent <strong>Commerce</strong> group).</li><li>Open <strong>Commerce -&gt; Product Management</strong> in the left sidebar.</li></ol><h2 id="list-page" tabindex="-1">List Page <a class="header-anchor" href="#list-page" aria-label="Permalink to &quot;List Page&quot;">​</a></h2><p>Path: <code>/_Admin/commerce/product-management?SiteId=...</code></p><table tabindex="0"><thead><tr><th>Area</th><th>Description</th></tr></thead><tbody><tr><td>Statistics</td><td>Out of stock count, total products, total inventory, etc.</td></tr><tr><td>Filters</td><td>Keyword, active status, stock status, etc.; click <strong>Search</strong> to refresh</td></tr><tr><td>Table columns</td><td>From <a href="./product-types.html">product types</a> and <strong>product custom fields</strong> in <a href="./settings.html">settings</a>; common: title, featured image, variant count, stock, sales, tags, categories</td></tr><tr><td><strong>Create product</strong></td><td>Dropdown: blank product, or select <strong>product type</strong> then <a href="./product-management-detail.html#how-to-enter">create page</a></td></tr><tr><td><strong>Edit</strong></td><td>Row pencil → <a href="./product-management-detail.html#how-to-enter">edit page</a></td></tr><tr><td><strong>Duplicate</strong></td><td>After selecting <strong>one</strong> row, toolbar <strong>Duplicate</strong> appears; confirm to create copy</td></tr><tr><td><strong>Batch delete</strong></td><td>Select rows → toolbar <strong>Delete</strong>; confirm to remove selected products</td></tr></tbody></table>',9)),i(a,{src:"/cms/commerce/product-management-list.png",alt:"Product management list: stats, filters, table and create product dropdown",width:"1120"}),t[1]||(t[1]=e('<div class="tip custom-block"><p class="custom-block-title">Variants</p><p>When <a href="./settings.html">settings</a> has not enabled &quot;Hide variants&quot;, list shows variant count; variant details maintained on <a href="./product-management-detail.html">product detail</a> page.</p></div><h2 id="digital-products" tabindex="-1">Digital Products <a class="header-anchor" href="#digital-products" aria-label="Permalink to &quot;Digital Products&quot;">​</a></h2><p>Digital products (ebooks, software licenses, downloadable assets, etc.) require a <strong>digital product</strong> <a href="./product-types.html#digital-products">product type</a> first, then create or edit specific products on this list.</p><table tabindex="0"><thead><tr><th>Step</th><th>Where</th></tr></thead><tbody><tr><td>1. Define type</td><td><a href="./product-types.html">Product types</a> — check <strong>Digital product</strong>, optional download count/day limits</td></tr><tr><td>2. Create product</td><td>This page <strong>Create product</strong> → select that type (or edit existing digital product)</td></tr><tr><td>3. Configure delivery</td><td><a href="./product-management-detail.html#digital-products">Product detail</a> — in variant table <strong>Digital products</strong> column, add file / link / text for <strong>each SKU</strong></td></tr></tbody></table><p>List summary or table often shows <strong>Digital product</strong> tag (<code>isDigital</code>) to distinguish from physical products. Delivery items are not maintained on list; click <strong>Edit</strong> for detail page.</p><p>If <a href="./settings.html">settings</a> enables <strong>Digital product delivery required</strong>, products without delivery on any variant <strong>cannot be saved</strong>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./product-management-detail.html">Product detail (create and edit)</a> — <a href="./product-management-detail.html#digital-products">digital product configuration</a></li><li><a href="./product-types.html">Product types</a> — <a href="./product-types.html#digital-products">digital product type</a></li><li><a href="./product-categories.html">Product categories</a></li><li><a href="./">Commerce overview</a></li></ul>',8))])}const b=r(s,[["render",c]]);export{f as __pageData,b as default};
